"use client";

import * as React from "react";
import { $getNodeByKey, $getSelection, $isRangeSelection, $isTextNode, COMMAND_PRIORITY_HIGH, KEY_DOWN_COMMAND, type LexicalNode, type NodeKey } from "lexical";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { findShortcodeTrigger, useEmojiSuggestions, type UseEmojiSuggestionsReturnValue, type UseEmojiSuggestionsOptions, type ShortcodeCompletion } from "emoji-components";

export type LexicalEmojiSuggestionsOptions = Omit<UseEmojiSuggestionsOptions, "trigger" | "element"> & {
  node?: (text: string, suggestion: ShortcodeCompletion) => LexicalNode;
};

type Match = { query: string; key: NodeKey; from: number; to: number };

function $matchAtSelection(): Match | null {
  const selection = $getSelection();
  if (!$isRangeSelection(selection) || !selection.isCollapsed()) return null;
  const { offset } = selection.anchor;
  const text = selection.anchor.getNode();
  if (!$isTextNode(text) || !text.isSimpleText()) return null;
  const found = findShortcodeTrigger(text.getTextContent().slice(0, offset));
  return found && { query: found.query, key: text.getKey(), from: found.offset, to: offset };
}

export function useLexicalEmojiSuggestions({ node, ...options }: LexicalEmojiSuggestionsOptions = {}): UseEmojiSuggestionsReturnValue {
  const [editor] = useLexicalComposerContext();
  const [match, setMatch] = React.useState<Match | null>(null);
  const suggestions = useEmojiSuggestions({
    ...options,
    element: () => editor.getRootElement(),
    trigger: match && {
      query: match.query,
      anchor() {
        const text = editor.getElementByKey(match.key)?.firstChild;
        if (!text) return null;
        const length = text.textContent?.length ?? 0;
        const range = document.createRange();
        range.setStart(text, Math.min(match.from, length));
        range.setEnd(text, Math.min(match.to, length));
        return range.getBoundingClientRect();
      },
      replace: (text, s) =>
        editor.update(() => {
          const target = $getNodeByKey(match.key);
          if (!$isTextNode(target)) return;
          const selection = target.select(match.from, match.to);
          if (node) selection.insertNodes([node(text, s)]);
          else selection.insertText(/\s/.test(target.getTextContent().charAt(match.to)) ? text : `${text} `);
        }),
    },
  });
  const { onKeyDown } = suggestions;
  React.useEffect(
    () =>
      editor.registerUpdateListener(({ editorState }) => editorState.read(() => setMatch($matchAtSelection()))),
    [editor],
  );
  React.useEffect(() => editor.registerCommand(KEY_DOWN_COMMAND, onKeyDown, COMMAND_PRIORITY_HIGH), [editor, onKeyDown]);
  return suggestions;
}

import { $createTextNode } from "lexical";
import { useLexicalEmojiSuggestions } from "@/hooks/use-emoji-lexical";
import { EmojiSuggestions } from "@/components/ui/emoji-suggestions";
import { $createEmojiNode } from "./emoji-node";

export function EmojiSuggestionsPlugin() {
  const emoji = useLexicalEmojiSuggestions({
    node: (text, { record, shortcode }) => (record.imageUrl ? $createEmojiNode({ unified: record.unified, shortcode, text: null }) : $createTextNode(`${text} `)),
  });
  return <EmojiSuggestions {...emoji} />;
}

import * as React from "react";
import { $applyNodeReplacement, DecoratorNode, TextNode, type EditorConfig, type NodeKey, type SerializedLexicalNode, type Spread } from "lexical";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { Emoji, useEmojiStore, type EmojiStore } from "emoji-components";

export type EmojiAttrs = {
  unified: string;
  shortcode: string;
  text: string | null;
};

type SerializedEmojiNode = Spread<EmojiAttrs, SerializedLexicalNode>;

export function emojiAttrs(store: EmojiStore, idOrShortcode: string): EmojiAttrs | null {
  const record = store.get(idOrShortcode) ?? store.fromShortcode(idOrShortcode);
  if (!record) return null;
  const unified = record.imageUrl ? record.unified : store.withSkinTone(record.unified);
  const text = record.imageUrl ? null : String.fromCodePoint(...unified.split("-").map((hex) => parseInt(hex, 16)));
  return { unified, shortcode: record.shortcodes[0] ?? record.unified, text };
}

export class EmojiNode extends DecoratorNode<React.JSX.Element> {
  __attrs: EmojiAttrs;

  static getType() {
    return "emoji";
  }

  static clone(node: EmojiNode) {
    return new EmojiNode(node.__attrs, node.__key);
  }

  static importJSON({ unified, shortcode, text }: SerializedEmojiNode) {
    return $createEmojiNode({ unified, shortcode, text });
  }

  constructor(attrs: EmojiAttrs, key?: NodeKey) {
    super(key);
    this.__attrs = attrs;
  }

  exportJSON(): SerializedEmojiNode {
    return { ...super.exportJSON(), ...this.__attrs, type: "emoji", version: 1 };
  }

  createDOM(_config: EditorConfig) {
    const span = document.createElement("span");
    span.className = "inline-block align-[-0.2em]";
    span.dataset.emojiNode = "";
    return span;
  }

  updateDOM() {
    return false;
  }

  isInline() {
    return true;
  }

  getTextContent() {
    return this.__attrs.text ?? `:${this.__attrs.shortcode}:`;
  }

  decorate() {
    return <Emoji emoji={this.__attrs.unified} size={20} className="inline-block size-[1.25em] leading-none" />;
  }
}

export function $createEmojiNode(attrs: EmojiAttrs) {
  return $applyNodeReplacement(new EmojiNode(attrs));
}

const SHORTCODE = /:([a-z0-9_+'-]+):/i;

export function EmojiShortcodePlugin() {
  const [editor] = useLexicalComposerContext();
  const store = useEmojiStore();
  React.useEffect(
    () =>
      editor.registerNodeTransform(TextNode, (node) => {
        if (!node.isSimpleText()) return;
        const match = SHORTCODE.exec(node.getTextContent());
        const attrs = match ? emojiAttrs(store, match[1]!) : null;
        if (!match || !attrs) return;
        const [, target] = match.index === 0 ? [null, node.splitText(match[0].length)[0]] : node.splitText(match.index, match.index + match[0].length);
        target?.replace($createEmojiNode(attrs)).selectNext();
      }),
    [editor, store],
  );
  return null;
}
